/**
 * "Blocked by" links between issues. Every read and write is org-scoped; the
 * links carry no archive state, so removal is a hard delete.
 *
 * Must call (do not reimplement): orgPredicate, livePredicate, toIssueDependency
 */
import { and, eq, inArray } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { toIsoTimestamp, type IssueId, type OrgId, type UserId } from "@/types/common";
import { CLOSED_ISSUE_STATUSES, type Issue, type IssueDependency } from "@/types/issue";
import { orgPredicate, livePredicate } from "./base-repository";
import { compact } from "./_paging";
import { findIssueById } from "./issue-repository";
import { toIssueDependency } from "./_mappers";

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toIssueDependency(row) : null;
}

/** Inserts a link; a concurrent insert of the same pair is absorbed. */
export async function insertDependency(input: {
  orgId: OrgId;
  issueId: IssueId;
  blockerId: IssueId;
  createdBy: UserId;
}): Promise<IssueDependency> {
  const db = getDb();
  db.insert(issueDependencies)
    .values({
      orgId: input.orgId,
      issueId: input.issueId,
      blockerId: input.blockerId,
      createdBy: input.createdBy,
      createdAt: toIsoTimestamp(new Date()),
    })
    .onConflictDoNothing()
    .run();

  const row = await findDependency(input.orgId, input.issueId, input.blockerId);
  if (!row) throw new Error("Issue dependency insert produced no row");
  return row;
}

/** Returns true when a link was removed. */
export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const rows = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .returning({ issueId: issueDependencies.issueId })
    .all();
  return rows.length > 0;
}

/** Ids of every issue that `blockerId` directly blocks. */
export async function listBlockedIds(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ issueId: issueDependencies.issueId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .all();
  return rows.map((row) => row.issueId as IssueId);
}

/** Ids of every issue that directly blocks `issueId`, archived or not. */
export async function listBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ blockerId: issueDependencies.blockerId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
      ),
    )
    .all();
  return rows.map((row) => row.blockerId as IssueId);
}

/**
 * Live blockers of `issueId` that are not yet closed. Archived blockers are
 * excluded: an archived issue no longer gates anything.
 */
export async function listOpenBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const ids = await listBlockerIds(orgId, issueId);
  if (ids.length === 0) return [];

  const rows = getDb()
    .select({ id: issues.id })
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.id, [...ids]),
          livePredicate(issues.archivedAt, {}),
          inArray(issues.status, ["backlog", "todo", "in_progress", "in_review"]),
        ),
      ),
    )
    .all();

  const open: Issue[] = [];
  for (const row of rows) {
    const issue = await findIssueById(orgId, row.id as IssueId);
    if (issue) open.push(issue);
  }
  return open;
}

/** Live blockers of `issueId` (open or closed), ordered by issue number. */
export async function listLiveBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const ids = await listBlockerIds(orgId, issueId);
  if (ids.length === 0) return [];

  const rows = getDb()
    .select({ id: issues.id })
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.id, [...ids]),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(issues.number)
    .all();

  const live: Issue[] = [];
  for (const row of rows) {
    const issue = await findIssueById(orgId, row.id as IssueId);
    if (issue) live.push(issue);
  }
  return live;
}

