/**
 * "Blocked by" links between issues: the rules that keep the graph acyclic and
 * the completion gate, plus the reaction that tells an assignee when their
 * issue has no open blockers left.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, emit, subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { issueResource, requireFound } from "./_support";
import { notify } from "./notification-service";
import type { IssueId, OrgId } from "@/types/common";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Unsubscribe } from "@/types/event";

/**
 * Raised by `changeIssueStatus` when an issue would move to `done` while it
 * still has open blockers. `blockerIds` names exactly those blockers.
 */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly blockerIds: readonly IssueId[]) {
    super(`Issue is blocked by ${blockerIds.length} open issue(s)`);
    this.name = "IssueBlockedError";
  }
}

/** Raised by `addBlocker` when the new link would close a cycle (or self-loop). */
export class IssueDependencyCycleError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly issueId: IssueId, readonly blockerId: IssueId) {
    super(`Issue ${blockerId} cannot block ${issueId}: that would create a cycle`);
    this.name = "IssueDependencyCycleError";
  }
}

export type IssueBlockerInput = {
  orgId: OrgId;
  issueId: IssueId;
  blockerId: IssueId;
};

function isClosed(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/**
 * True when `target` is reachable from `start` by following "blocked by"
 * links. Adding `issueId blocked by blockerId` closes a cycle exactly when
 * `issueId` is reachable from `blockerId`.
 */
async function isReachable(
  orgId: OrgId,
  start: IssueId,
  target: IssueId,
): Promise<boolean> {
  const seen = new Set<IssueId>([start]);
  const queue: IssueId[] = [start];

  while (queue.length > 0) {
    const current = queue.shift() as IssueId;
    if (current === target) return true;

    for (const next of await dependencyRepo.listBlockerIds(orgId, current)) {
      if (!seen.has(next)) {
        seen.add(next);
        queue.push(next);
      }
    }
  }
  return false;
}

async function loadBlockedIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
  action: "issue:update" | "issue:read",
): Promise<Issue> {
  assertOrgScope(actor, orgId);
  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, action, issueResource(issue));
  return issue;
}

/** Records "`issueId` is blocked by `blockerId`". Adding an existing link returns it. */
export async function addBlocker(
  actor: Actor,
  input: IssueBlockerInput,
): Promise<IssueDependency> {
  const blocked = await loadBlockedIssue(
    actor,
    input.orgId,
    input.issueId,
    "issue:update",
  );
  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );

  assertNotArchived("Issue", blocked.id, blocked);
  assertNotArchived("Issue", blocker.id, blocker);

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
  if (existing) return existing;

  if (
    input.issueId === input.blockerId ||
    (await isReachable(input.orgId, input.blockerId, input.issueId))
  ) {
    throw new IssueDependencyCycleError(input.issueId, input.blockerId);
  }

  return dependencyRepo.insertDependency({
    orgId: input.orgId,
    issueId: input.issueId,
    blockerId: input.blockerId,
    createdBy: actor.userId,
  });
}

/** Deletes the link. Resolves `true` if one was removed, `false` if none existed. */
export async function removeBlocker(
  actor: Actor,
  input: IssueBlockerInput,
): Promise<boolean> {
  await loadBlockedIssue(actor, input.orgId, input.issueId, "issue:update");
  return dependencyRepo.deleteDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
}

/** Live blockers of `issueId` (open or closed), ordered by issue number. */
export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  await loadBlockedIssue(actor, orgId, issueId, "issue:read");
  return dependencyRepo.listLiveBlockers(orgId, issueId);
}

/**
 * Sends `issue_unblocked` to each issue that `blockerId` just stopped
 * blocking, when that issue is still live, open, assigned and now free of
 * open blockers.
 */
async function notifyUnblockedDependents(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: Parameters<typeof notify>[3]["actorId"],
): Promise<void> {
  for (const blockedId of await dependencyRepo.listBlockedIds(orgId, blockerId)) {
    const blocked = await issueRepo.findIssueById(orgId, blockedId);
    if (!blocked || blocked.assigneeId === null) continue;
    if (blocked.archivedAt !== null || isClosed(blocked.status)) continue;

    const open = await dependencyRepo.listLiveBlockers(orgId, blockedId, {
      openOnly: true,
    });
    if (open.length > 0) continue;

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "An issue is unblocked",
      body: `Issue ${blocked.id} has no open blockers left`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}

/**
 * The bus wiring for the unblock reaction. Attached from `event-registry`
 * alongside the other `register*Listeners` groups.
 */
export function registerIssueDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosed(payload.from) || !isClosed(payload.to)) return;
      await notifyUnblockedDependents(payload.orgId, payload.issueId, payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      const archived = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (!archived || isClosed(archived.status)) return;
      await notifyUnblockedDependents(payload.orgId, payload.issueId, payload.actorId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}
EOF
